from pathlib import Path

def replace_between(text, start, end, new):
    a=text.find(start); b=text.find(end,a+1)
    if a<0 or b<0: raise SystemExit(f'anchor missing: {start} -> {end}')
    return text[:a]+new.rstrip()+'\n\n'+text[b:]

p=Path('buildsrc/store-app/src/main/java/com/attendpro/store/StoreVoiceControl1975Activity.kt'); p.parent.mkdir(parents=True,exist_ok=True); p.write_text('package com.attendpro.store\n\nimport android.app.Activity\nimport android.app.AlertDialog\nimport android.os.Bundle\nimport android.text.InputType\nimport android.view.Gravity\nimport android.view.View\nimport android.widget.CheckBox\nimport android.widget.EditText\nimport android.widget.LinearLayout\nimport android.widget.ScrollView\nimport android.widget.TextView\nimport com.attendpro.core.StoreRepository\nimport com.attendpro.core.UiKit\n\nclass StoreVoiceControl1975Activity : Activity() {\n    private lateinit var repo: StoreRepository\n    private val p by lazy { UiKit.palette(this) }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        repo = StoreRepository(this)\n        showPage()\n    }\n\n    private fun showPage() {\n        window.statusBarColor = p.bg\n        val root = LinearLayout(this).apply {\n            orientation = LinearLayout.VERTICAL\n            layoutDirection = View.LAYOUT_DIRECTION_RTL\n            gravity = Gravity.CENTER_HORIZONTAL\n            setPadding(UiKit.dp(this@StoreVoiceControl1975Activity, 16), UiKit.dp(this@StoreVoiceControl1975Activity, 18), UiKit.dp(this@StoreVoiceControl1975Activity, 16), UiKit.dp(this@StoreVoiceControl1975Activity, 30))\n            setBackgroundColor(p.bg)\n        }\n        val hero = UiKit.heroCard(this, p)\n        hero.addView(UiKit.title(this, p, "الصوت والتنبيهات", 24f).apply { gravity = Gravity.CENTER; setTextColor(android.graphics.Color.WHITE) })\n        hero.addView(UiKit.subtitle(this, p, "تحكم عام + إعداد مستقل لكل موظف. هذه الإعدادات لا تغيّر التحقق ببصمة الصوت ولا الاقتران.").apply { gravity = Gravity.CENTER; setTextColor(android.graphics.Color.argb(225,255,255,255)) })\n        root.addView(hero)\n\n        val general = UiKit.card(this, p)\n        general.addView(UiKit.sectionLabel(this, p, "التحكم العام في جهاز المحل"))\n        val attendance = check("نطق تسجيل الحضور والانصراف", repo.storeVoiceAttendanceEnabled)\n        val request = check("نطق إرسال طلب إثبات الوجود", repo.storeVoiceRequestEnabled)\n        val late = check("نطق تنبيه التأخير", repo.storeVoiceLateEnabled)\n        val missing = check("نطق عدم إثبات الوجود", repo.storeVoiceMissingProofEnabled)\n        val enabled = check("السماح بالنطق في جهاز المحل", repo.attendanceVoiceAnnouncementEnabled)\n        listOf(enabled, attendance, request, late, missing).forEach { general.addView(it) }\n        root.addView(general)\n\n        val employeeGeneral = UiKit.card(this, p)\n        employeeGeneral.addView(UiKit.sectionLabel(this, p, "التحكم العام في هاتف الموظف"))\n        val employeePrompts = check("السماح بالتنبيهات الصوتية المعتادة على هاتف الموظف", repo.employeeVoicePromptsEnabled)\n        val messageVoice = check("اجعل الرسائل الجديدة صوتية افتراضيًا", repo.employeeMessageVoiceDefaultEnabled)\n        employeeGeneral.addView(employeePrompts)\n        employeeGeneral.addView(messageVoice)\n        employeeGeneral.addView(UiKit.subtitle(this, p, "يمكن تجاوز الإعداد العام لكل موظف من القسم التالي: يرث الإعداد العام، صوت + إشعار، إشعار فقط، أو صامت."))\n        root.addView(employeeGeneral)\n\n        val tuning = UiKit.card(this, p)\n        tuning.addView(UiKit.sectionLabel(this, p, "الصوت والعبارات"))\n        val rate = numberField("سرعة النطق % (50–150)", repo.voiceRatePercent)\n        val volume = numberField("مستوى الصوت % (0–100)", repo.voiceVolumePercent)\n        val sentText = UiKit.field(this, p, "عبارة إرسال طلب الإثبات").apply { setText(repo.voiceRequestSentText) }\n        val lateText = UiKit.field(this, p, "عبارة التأخير").apply { setText(repo.voiceLateText) }\n        val missingText = UiKit.field(this, p, "عبارة عدم الإثبات").apply { setText(repo.voiceMissingProofText) }\n        listOf(rate, volume, sentText, lateText, missingText).forEach { tuning.addView(it) }\n        tuning.addView(UiKit.button(this, p, "تجربة النطق", false).apply {\n            setOnClickListener {\n                repo.attendanceVoiceAnnouncementEnabled = true\n                StoreVoiceAnnouncer(this@StoreVoiceControl1975Activity, repo).apply { speak("اختبار الصوت في إدارة المحل"); android.os.Handler(mainLooper).postDelayed({ shutdown() }, 3500) }\n            }\n        })\n        root.addView(tuning)\n\n        val perEmployee = UiKit.card(this, p)\n        perEmployee.addView(UiKit.sectionLabel(this, p, "إعداد صوتي خاص لكل موظف"))\n        val active = repo.employees().filter { it.active }\n        if (active.isEmpty()) perEmployee.addView(UiKit.subtitle(this, p, "لا يوجد موظفون نشطون حاليًا."))\n        active.forEach { employee ->\n            val label = TextView(this).apply {\n                text = "${employee.displayName} • ${voiceModeArabic(repo.employeeMessageVoiceMode(employee.employeeId))}"\n                textSize = 15f; gravity = Gravity.RIGHT; setTextColor(p.text)\n                setPadding(0, UiKit.dp(this@StoreVoiceControl1975Activity, 6), 0, UiKit.dp(this@StoreVoiceControl1975Activity, 3))\n            }\n            perEmployee.addView(label)\n            perEmployee.addView(UiKit.button(this, p, "تخصيص ${employee.displayName}", false).apply {\n                setOnClickListener { chooseEmployeeMode(employee.employeeId, employee.displayName) }\n            })\n        }\n        root.addView(perEmployee)\n\n        val save = UiKit.card(this, p)\n        save.addView(UiKit.button(this, p, "حفظ إعدادات الصوت").apply {\n            setOnClickListener {\n                repo.attendanceVoiceAnnouncementEnabled = enabled.isChecked\n                repo.storeVoiceAttendanceEnabled = attendance.isChecked\n                repo.storeVoiceRequestEnabled = request.isChecked\n                repo.storeVoiceLateEnabled = late.isChecked\n                repo.storeVoiceMissingProofEnabled = missing.isChecked\n                repo.employeeVoicePromptsEnabled = employeePrompts.isChecked\n                repo.employeeMessageVoiceDefaultEnabled = messageVoice.isChecked\n                repo.voiceRatePercent = rate.text.toString().toIntOrNull() ?: repo.voiceRatePercent\n                repo.voiceVolumePercent = volume.text.toString().toIntOrNull() ?: repo.voiceVolumePercent\n                repo.voiceRequestSentText = sentText.text.toString().trim()\n                repo.voiceLateText = lateText.text.toString().trim()\n                repo.voiceMissingProofText = missingText.text.toString().trim()\n                AlertDialog.Builder(this@StoreVoiceControl1975Activity).setTitle("تم الحفظ").setMessage("تم تحديث إعدادات النطق والتنبيهات الصوتية دون تغيير إعدادات التحقق الصوتي أو الارتباط.").setPositiveButton("حسنًا", null).show()\n            }\n        })\n        save.addView(UiKit.button(this, p, "رجوع", false).apply { setOnClickListener { finish() } })\n        root.addView(save)\n        setContentView(ScrollView(this).apply { setBackgroundColor(p.bg); addView(root) })\n    }\n\n    private fun check(text: String, value: Boolean) = CheckBox(this).apply {\n        this.text = text; isChecked = value; textSize = 15f; gravity = Gravity.RIGHT\n        layoutDirection = View.LAYOUT_DIRECTION_RTL; setTextColor(p.text)\n    }\n\n    private fun numberField(hint: String, value: Int) = UiKit.field(this, p, hint, true).apply {\n        inputType = InputType.TYPE_CLASS_NUMBER; setText(value.toString())\n    }\n\n    private fun chooseEmployeeMode(employeeId: String, name: String) {\n        val values = arrayOf("INHERIT", "VOICE_NOTIFICATION", "NOTIFICATION_ONLY", "SILENT")\n        val labels = arrayOf("يتبع الإعداد العام", "صوت + إشعار", "إشعار فقط", "صامت")\n        val current = values.indexOf(repo.employeeMessageVoiceMode(employeeId)).coerceAtLeast(0)\n        AlertDialog.Builder(this).setTitle("تنبيهات $name").setSingleChoiceItems(labels, current) { dialog, which ->\n            repo.setEmployeeMessageVoiceMode(employeeId, values[which]); dialog.dismiss(); showPage()\n        }.setNegativeButton("إلغاء", null).show()\n    }\n\n    private fun voiceModeArabic(value: String) = when (value) {\n        "VOICE_NOTIFICATION" -> "صوت + إشعار"\n        "NOTIFICATION_ONLY" -> "إشعار فقط"\n        "SILENT" -> "صامت"\n        else -> "يتبع العام"\n    }\n}\n',encoding='utf-8')
p=Path('buildsrc/store-app/src/main/java/com/attendpro/store/StoreMessages1975Activity.kt'); p.parent.mkdir(parents=True,exist_ok=True); p.write_text('package com.attendpro.store\n\nimport android.app.Activity\nimport android.app.AlertDialog\nimport android.os.Bundle\nimport android.view.Gravity\nimport android.view.View\nimport android.widget.CheckBox\nimport android.widget.EditText\nimport android.widget.LinearLayout\nimport android.widget.ScrollView\nimport android.widget.Spinner\nimport android.widget.ArrayAdapter\nimport android.widget.TextView\nimport android.widget.Toast\nimport com.attendpro.core.CentralServerClient\nimport com.attendpro.core.DeviceIdentity\nimport com.attendpro.core.StoreRepository\nimport com.attendpro.core.UiKit\nimport java.text.SimpleDateFormat\nimport java.util.Date\nimport java.util.Locale\n\nclass StoreMessages1975Activity : Activity() {\n    private lateinit var repo: StoreRepository\n    private lateinit var identity: DeviceIdentity\n    private val p by lazy { UiKit.palette(this) }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        repo = StoreRepository(this)\n        identity = DeviceIdentity(this)\n        showInbox()\n        StoreMessagePoll1975.schedule(this)\n    }\n\n    private fun showInbox() {\n        val root = base("الرسائل والإشعارات", "رسائل إدارة النظام وردود الموظفين ورسائل المحل")\n        val actions = UiKit.card(this, p)\n        actions.addView(UiKit.button(this, p, "✉ إرسال رسالة لموظف").apply { setOnClickListener { composeEmployee() } })\n        actions.addView(UiKit.button(this, p, "↻ تحديث الوارد", false).apply { setOnClickListener { loadMessages(root) } })\n        root.addView(actions)\n        loadMessages(root)\n    }\n\n    private fun loadMessages(root: LinearLayout) {\n        Thread {\n            val result = CentralServerClient.storeMessagesInbox(repo.serverUrl, repo.centralAccessToken, repo.storeId, identity, 100)\n            runOnUiThread {\n                result.onSuccess { messages -> renderMessages(root, messages) }\n                    .onFailure { toast("تعذر تحميل الرسائل: ${it.message}") }\n            }\n        }.start()\n    }\n\n    private fun renderMessages(root: LinearLayout, messages: List<CentralServerClient.Message1975>) {\n        while (root.childCount > 2) root.removeViewAt(2)\n        val card = UiKit.card(this, p)\n        card.addView(UiKit.sectionLabel(this, p, "الوارد"))\n        if (messages.isEmpty()) card.addView(UiKit.subtitle(this, p, "لا توجد رسائل حاليًا."))\n        messages.forEach { message ->\n            val unread = message.readAt <= 0L\n            val sender = when (message.senderType) { "SYSTEM_OWNER" -> "إدارة النظام"; "EMPLOYEE" -> "الموظف ${message.employeeId}"; else -> "إدارة المحل" }\n            val title = TextView(this).apply {\n                text = "${if (unread) "● " else ""}${message.title.ifBlank { "رسالة" }} • $sender"\n                textSize = 16f; gravity = Gravity.RIGHT; setTextColor(p.text)\n                setTypeface(typeface, android.graphics.Typeface.BOLD)\n                setPadding(0, UiKit.dp(this@StoreMessages1975Activity, 8), 0, 2)\n            }\n            card.addView(title)\n            card.addView(UiKit.subtitle(this, p, "${message.body}\\n${time(message.createdAt)} • ${priorityArabic(message.priority)}"))\n            card.addView(UiKit.button(this, p, if (unread) "تعليم كمقروء" else "مقروء ✓", false).apply {\n                isEnabled = unread\n                setOnClickListener { markRead(message.messageId) }\n            })\n        }\n        root.addView(card)\n        val back = UiKit.card(this, p)\n        back.addView(UiKit.button(this, p, "رجوع", false).apply { setOnClickListener { finish() } })\n        root.addView(back)\n        setContentView(ScrollView(this).apply { setBackgroundColor(p.bg); addView(root) })\n    }\n\n    private fun composeEmployee() {\n        val employees = repo.employees().filter { it.active }\n        if (employees.isEmpty()) { toast("لا يوجد موظفون نشطون"); return }\n        val names = employees.map { "${it.displayName} • ${it.employeeId}" }.toTypedArray()\n        AlertDialog.Builder(this).setTitle("اختر الموظف").setItems(names) { _, index -> composeFor(employees[index].employeeId, employees[index].displayName) }.setNegativeButton("إلغاء", null).show()\n    }\n\n    private fun composeFor(employeeId: String, name: String) {\n        val box = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; layoutDirection = View.LAYOUT_DIRECTION_RTL; setPadding(28, 8, 28, 0) }\n        val title = UiKit.field(this, p, "عنوان الرسالة").apply { setText("رسالة من إدارة المحل") }\n        val message = UiKit.field(this, p, "اكتب الرسالة التي تريد إرسالها").apply { minLines = 3 }\n        val priority = Spinner(this).apply { adapter = ArrayAdapter(this@StoreMessages1975Activity, android.R.layout.simple_spinner_dropdown_item, arrayOf("عادية", "مهمة", "عاجلة")) }\n        val mode = repo.employeeMessageVoiceMode(employeeId)\n        val defaultVoice = when (mode) { "VOICE_NOTIFICATION" -> true; "NOTIFICATION_ONLY", "SILENT" -> false; else -> repo.employeeMessageVoiceDefaultEnabled }\n        val voice = CheckBox(this).apply { text = "قراءة الرسالة بصوت على هاتف الموظف"; isChecked = defaultVoice; gravity = Gravity.RIGHT; layoutDirection = View.LAYOUT_DIRECTION_RTL }\n        box.addView(title); box.addView(message); box.addView(priority); box.addView(voice)\n        if (mode == "SILENT") box.addView(UiKit.subtitle(this, p, "تنبيه: إعداد هذا الموظف مضبوط على صامت. يمكنك إرسال الرسالة، لكن لن يتم تشغيل النطق تلقائيًا."))\n        val d = AlertDialog.Builder(this).setTitle("رسالة إلى $name").setView(box).setPositiveButton("إرسال", null).setNegativeButton("إلغاء", null).create()\n        d.setOnShowListener {\n            d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener {\n                val body = message.text.toString().trim()\n                if (body.isBlank()) { message.error = "اكتب الرسالة"; return@setOnClickListener }\n                val pr = when (priority.selectedItemPosition) { 2 -> "URGENT"; 1 -> "IMPORTANT"; else -> "NORMAL" }\n                d.getButton(AlertDialog.BUTTON_POSITIVE).isEnabled = false\n                Thread {\n                    val r = CentralServerClient.sendStoreMessageToEmployee(repo.serverUrl, repo.centralAccessToken, repo.storeId, identity, employeeId, title.text.toString(), body, pr, voice.isChecked && mode != "SILENT")\n                    runOnUiThread {\n                        r.onSuccess { toast("تم إرسال الرسالة إلى $name"); d.dismiss(); showInbox() }\n                            .onFailure { toast("تعذر الإرسال: ${it.message}"); d.getButton(AlertDialog.BUTTON_POSITIVE).isEnabled = true }\n                    }\n                }.start()\n            }\n        }\n        d.show()\n    }\n\n    private fun markRead(messageId: String) {\n        Thread {\n            CentralServerClient.markStoreMessageRead(repo.serverUrl, repo.centralAccessToken, repo.storeId, identity, messageId)\n            runOnUiThread { showInbox() }\n        }.start()\n    }\n\n    private fun base(title: String, subtitle: String) = LinearLayout(this).apply {\n        orientation = LinearLayout.VERTICAL; layoutDirection = View.LAYOUT_DIRECTION_RTL; gravity = Gravity.CENTER_HORIZONTAL\n        setPadding(UiKit.dp(this@StoreMessages1975Activity,16), UiKit.dp(this@StoreMessages1975Activity,18), UiKit.dp(this@StoreMessages1975Activity,16), UiKit.dp(this@StoreMessages1975Activity,30)); setBackgroundColor(p.bg)\n        val hero = UiKit.heroCard(this@StoreMessages1975Activity, p)\n        hero.addView(UiKit.title(this@StoreMessages1975Activity, p, title, 24f).apply { gravity=Gravity.CENTER; setTextColor(android.graphics.Color.WHITE) })\n        hero.addView(UiKit.subtitle(this@StoreMessages1975Activity, p, subtitle).apply { gravity=Gravity.CENTER; setTextColor(android.graphics.Color.argb(225,255,255,255)) })\n        addView(hero)\n    }\n\n    private fun priorityArabic(v: String) = when(v) { "URGENT" -> "عاجلة"; "IMPORTANT" -> "مهمة"; else -> "عادية" }\n    private fun time(ms: Long) = if (ms <= 0L) "" else SimpleDateFormat("dd/MM HH:mm", Locale.getDefault()).format(Date(ms))\n    private fun toast(s: String) = Toast.makeText(this, s, Toast.LENGTH_LONG).show()\n}\n',encoding='utf-8')
p=Path('buildsrc/store-app/src/main/java/com/attendpro/store/StoreMessagePoll1975.kt'); p.parent.mkdir(parents=True,exist_ok=True); p.write_text('package com.attendpro.store\n\nimport android.app.AlarmManager\nimport android.app.Notification\nimport android.app.NotificationChannel\nimport android.app.NotificationManager\nimport android.app.PendingIntent\nimport android.content.BroadcastReceiver\nimport android.content.Context\nimport android.content.Intent\nimport android.os.Build\nimport com.attendpro.core.CentralServerClient\nimport com.attendpro.core.DeviceIdentity\nimport com.attendpro.core.StoreRepository\n\nclass StoreMessagePoll1975 : BroadcastReceiver() {\n    override fun onReceive(context: Context) {\n        val pending = goAsync()\n        Thread {\n            try {\n                val repo = StoreRepository(context)\n                if (!repo.isCentralActivationActive()) return@Thread\n                val result = CentralServerClient.storeMessagesInbox(repo.serverUrl, repo.centralAccessToken, repo.storeId, DeviceIdentity(context), 50)\n                result.getOrNull().orEmpty().filter { it.readAt <= 0L }.forEach { message -> notify(context, repo, message) }\n            } finally {\n                schedule(context); pending.finish()\n            }\n        }.start()\n    }\n\n\n    private fun notify(context: Context, repo: StoreRepository, message: CentralServerClient.Message1975) {\n        if (repo.wasStoreMessageNotified1975(message.messageId)) return\n        repo.markStoreMessageNotified1975(message.messageId)\n        val nm=context.getSystemService(NotificationManager::class.java)?:return\n        val channel="attend_store_messages_1975"\n        if(Build.VERSION.SDK_INT>=26) nm.createNotificationChannel(NotificationChannel(channel,"رسائل إدارة المحل",NotificationManager.IMPORTANCE_HIGH))\n        val open=PendingIntent.getActivity(context,message.messageId.hashCode(),Intent(context,StoreMessages1975Activity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n        val sender=if(message.senderType=="SYSTEM_OWNER")"إدارة النظام" else "الموظف ${message.employeeId}"\n        val b=if(Build.VERSION.SDK_INT>=26) Notification.Builder(context,channel) else @Suppress("DEPRECATION") Notification.Builder(context)\n        nm.notify(58000+(message.messageId.hashCode() and 0x7fff),b.setSmallIcon(R.drawable.ic_attend_pro).setContentTitle("${message.title.ifBlank{"رسالة"}} • $sender").setContentText(message.body).setStyle(Notification.BigTextStyle().bigText(message.body)).setAutoCancel(true).setContentIntent(open).setPriority(Notification.PRIORITY_HIGH).build())\n    }\n\n    companion object {\n        private const val ACTION="com.attendpro.store.ACTION_MESSAGE_POLL_1975"\n        fun schedule(context: Context) {\n            val am=context.getSystemService(AlarmManager::class.java)?:return\n            val intent=Intent(context,StoreMessagePoll1975::class.java).setAction(ACTION)\n            val pi=PendingIntent.getBroadcast(context,1975,intent,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n            val at=System.currentTimeMillis()+5*60_000L\n            runCatching { am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi) }.onFailure { am.set(AlarmManager.RTC_WAKEUP,at,pi) }\n        }\n    }\n}\n',encoding='utf-8')
p=Path('buildsrc/employee-app/src/main/java/com/attendpro/employee/EmployeeMessages1975Activity.kt'); p.parent.mkdir(parents=True,exist_ok=True); p.write_text('package com.attendpro.employee\n\nimport android.app.Activity\nimport android.app.AlertDialog\nimport android.os.Bundle\nimport android.view.Gravity\nimport android.view.View\nimport android.widget.LinearLayout\nimport android.widget.ScrollView\nimport android.widget.TextView\nimport android.widget.Toast\nimport com.attendpro.core.CentralServerClient\nimport com.attendpro.core.EmployeeIdentityStore\nimport com.attendpro.core.UiKit\nimport java.text.SimpleDateFormat\nimport java.util.Date\nimport java.util.Locale\n\nclass EmployeeMessages1975Activity : Activity() {\n    private lateinit var identity: EmployeeIdentityStore\n    private val p by lazy { UiKit.palette(this) }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        identity = EmployeeIdentityStore(this)\n        load()\n    }\n\n    private fun load() {\n        val root = LinearLayout(this).apply {\n            orientation = LinearLayout.VERTICAL; layoutDirection = View.LAYOUT_DIRECTION_RTL; gravity = Gravity.CENTER_HORIZONTAL\n            setPadding(UiKit.dp(this@EmployeeMessages1975Activity,16), UiKit.dp(this@EmployeeMessages1975Activity,18), UiKit.dp(this@EmployeeMessages1975Activity,16), UiKit.dp(this@EmployeeMessages1975Activity,30)); setBackgroundColor(p.bg)\n        }\n        val hero = UiKit.heroCard(this, p)\n        hero.addView(UiKit.title(this,p,"الرسائل والإشعارات",24f).apply { gravity=Gravity.CENTER; setTextColor(android.graphics.Color.WHITE) })\n        hero.addView(UiKit.subtitle(this,p,"رسائل إدارة النظام وإدارة المحل").apply { gravity=Gravity.CENTER; setTextColor(android.graphics.Color.argb(225,255,255,255)) })\n        root.addView(hero)\n        val loading = UiKit.card(this,p).apply { addView(UiKit.subtitle(this@EmployeeMessages1975Activity,p,"يجري تحميل الرسائل…")) }\n        root.addView(loading)\n        setContentView(ScrollView(this).apply { setBackgroundColor(p.bg); addView(root) })\n        Thread {\n            val r = CentralServerClient.employeeMessages(identity.serverUrl, identity.trustedStoreId, identity.employeeId, identity.pairingSecret, identity.installationId, true, 100)\n            runOnUiThread {\n                root.removeView(loading)\n                r.onSuccess { messages ->\n                    if (messages.isEmpty()) root.addView(UiKit.card(this,p).apply { addView(UiKit.subtitle(this@EmployeeMessages1975Activity,p,"لا توجد رسائل حاليًا.")) })\n                    messages.forEach { m ->\n                        val card = UiKit.card(this,p)\n                        val sender = if (m.senderType == "SYSTEM_OWNER") "إدارة نظام ATTEND PRO" else "إدارة المحل"\n                        card.addView(UiKit.sectionLabel(this,p,if (m.readAt <= 0L) "● $sender" else sender))\n                        card.addView(UiKit.title(this,p,m.title.ifBlank { "رسالة" },18f))\n                        card.addView(UiKit.subtitle(this,p,"${m.body}\\n${time(m.createdAt)} • ${priorityArabic(m.priority)}"))\n                        if (m.readAt <= 0L) card.addView(UiKit.button(this,p,"تعليم كمقروء",false).apply { setOnClickListener { markRead(m.messageId) } })\n                        card.addView(UiKit.button(this,p,"رد",false).apply { setOnClickListener { reply(m) } })\n                        root.addView(card)\n                    }\n                    root.addView(UiKit.card(this,p).apply {\n                        addView(UiKit.button(this@EmployeeMessages1975Activity,p,"تحديث",false).apply { setOnClickListener { load() } })\n                        addView(UiKit.button(this@EmployeeMessages1975Activity,p,"رجوع",false).apply { setOnClickListener { finish() } })\n                    })\n                }.onFailure { toast("تعذر تحميل الرسائل: ${it.message}") }\n            }\n        }.start()\n    }\n\n    private fun markRead(id: String) {\n        Thread {\n            CentralServerClient.markEmployeeMessageRead(identity.serverUrl, identity.trustedStoreId, identity.employeeId, identity.pairingSecret, identity.installationId, id)\n            runOnUiThread { load() }\n        }.start()\n    }\n\n    private fun reply(parent: CentralServerClient.Message1975) {\n        val field = com.attendpro.core.UiKit.field(this,p,"اكتب ردك").apply { minLines=3 }\n        val d = AlertDialog.Builder(this).setTitle("رد على الرسالة").setView(field).setPositiveButton("إرسال",null).setNegativeButton("إلغاء",null).create()\n        d.setOnShowListener {\n            d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener {\n                val message = field.text.toString().trim(); if (message.isBlank()) { field.error="اكتب الرد"; return@setOnClickListener }\n                Thread {\n                    val r=CentralServerClient.replyEmployeeMessage(identity.serverUrl,identity.trustedStoreId,identity.employeeId,identity.pairingSecret,identity.installationId,parent.messageId,message)\n                    runOnUiThread { r.onSuccess { toast("تم إرسال الرد"); d.dismiss(); markRead(parent.messageId) }.onFailure { toast("تعذر إرسال الرد: ${it.message}") } }\n                }.start()\n            }\n        }; d.show()\n    }\n\n    private fun priorityArabic(v:String)=when(v){"URGENT"->"عاجلة";"IMPORTANT"->"مهمة";else->"عادية"}\n    private fun time(ms:Long)=if(ms<=0L)"" else SimpleDateFormat("dd/MM HH:mm",Locale.getDefault()).format(Date(ms))\n    private fun toast(s:String)=Toast.makeText(this,s,Toast.LENGTH_LONG).show()\n}\n',encoding='utf-8')
p=Path('buildsrc/employee-app/src/main/java/com/attendpro/employee/EmployeeMessageNotifier1975.kt'); p.parent.mkdir(parents=True,exist_ok=True); p.write_text('package com.attendpro.employee\n\nimport android.app.Notification\nimport android.app.NotificationChannel\nimport android.app.NotificationManager\nimport android.app.PendingIntent\nimport android.content.Context\nimport android.content.Intent\nimport android.os.Build\nimport com.attendpro.core.CentralServerClient\nimport com.attendpro.core.EmployeeIdentityStore\n\nobject EmployeeMessageNotifier1975 {\n    private const val CHANNEL = "attend_employee_messages_1975"\n\n    fun notify(context: Context, message: CentralServerClient.Message1975) {\n        val identity = EmployeeIdentityStore(context)\n        if (identity.wasMessageNotified1975(message.messageId)) return\n        identity.markMessageNotified1975(message.messageId)\n        val nm = context.getSystemService(NotificationManager::class.java) ?: return\n        if (Build.VERSION.SDK_INT >= 26) {\n            nm.createNotificationChannel(NotificationChannel(CHANNEL, "رسائل ATTEND PRO", NotificationManager.IMPORTANCE_HIGH).apply {\n                description = "رسائل إدارة النظام وإدارة المحل"\n            })\n        }\n        val open = PendingIntent.getActivity(context, message.messageId.hashCode(), Intent(context, EmployeeMessages1975Activity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP), PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n        val sender = if (message.senderType == "SYSTEM_OWNER") "إدارة النظام" else "إدارة المحل"\n        val b = if (Build.VERSION.SDK_INT >= 26) Notification.Builder(context, CHANNEL) else @Suppress("DEPRECATION") Notification.Builder(context)\n        val n = b.setSmallIcon(com.attendpro.employee.R.drawable.ic_attend_pro)\n            .setContentTitle("${message.title.ifBlank { "رسالة" }} • $sender")\n            .setContentText(message.body)\n            .setStyle(Notification.BigTextStyle().bigText(message.body))\n            .setAutoCancel(true).setContentIntent(open).setPriority(Notification.PRIORITY_HIGH).build()\n        nm.notify(59000 + (message.messageId.hashCode() and 0x7fff), n)\n        if (message.voiceEnabled && identity.employeeVoicePromptsEnabled) {\n            EmployeeVoicePrompter(context).apply { speak("${message.title}. ${message.body}"); android.os.Handler(context.mainLooper).postDelayed({ shutdown() }, 8000) }\n        }\n    }\n}\n',encoding='utf-8')

